 "content": "def transform(grid):
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])

    # A horizontal 5-bar is a ruler: repeat the sequence attached below/above
    # its first cell across the full bar.
    for r in range(h):
        c = 0
        while c < w:
            if src[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and src[r][c] == 5:
                c += 1
            b = c
            if b - a < 2:
                continue
            for dr in (1, -1):
                rr = r + dr
                seq = []
                while 0 <= rr < h and src[rr][a] not in (0, 5):
                    seq.append(src[rr][a])
                    rr += dr
                for k, value in enumerate(seq):
                    rr = r + dr * (k + 1)
                    for x in range(a, b):
                        if out[rr][x] == 0:
                            out[rr][x] = value

    # A vertical 5-bar repeats the colored strip attached beside one endpoint.
    for c in range(w):
        r = 0
        while r < h:
            if src[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and src[r][c] == 5:
                r += 1
            b = r
            if b - a < 2:
                continue
            for dc in (1, -1):
                nc = c + dc
                if not 0 <= nc < w:
                    continue
                # Prefer the bottom endpoint; collect a multi-row tile attached there.
                tile_rows = []
                rr = b - 1
                while rr >= a and src[rr][nc] not in (0, 5):
                    vals = []
                    x = nc
                    while 0 <= x < w and src[rr][x] not in (0, 5):
                        vals.append(src[rr][x])
                        x += dc
                    tile_rows.append(vals)
                    rr -= 1
                if not tile_rows:
                    # A matching tile may instead be attached at the top endpoint.
                    rr = a
                    while rr < b and src[rr][nc] not in (0, 5):
                        vals = []
                        x = nc
                        while 0 <= x < w and src[rr][x] not in (0, 5):
                            vals.append(src[rr][x])
                            x += dc
                        tile_rows.append(vals)
                        rr += 1
                    top_attached = True
                else:
                    top_attached = False
                if not tile_rows:
                    continue
                tile_rows.reverse()
                height = len(tile_rows)
                anchor = a if top_attached else b - 1
                for rr in range(a, b):
                    idx = (rr - anchor) % height
                    pattern = tile_rows[idx]
                    for k, value in enumerate(pattern):
                        x = nc + dc * k
                        if 0 <= x < w and out[rr][x] == 0:
                            out[rr][x] = value
    return out
